import json
import urllib.request

creds = {}
with open('/app/.hermes/.env', 'r') as f:
    for line in f:
        if '=' in line:
            k, v = line.strip().split('=', 1)
            creds[k] = v

app_id = creds.get('FEISHU_APP_ID', '')
app_secret = creds.get('FEISHU_APP_SECRET', '')

url = 'https://open.feishu.cn/open-apis/auth/v3/tenant_access_token/internal'
data = json.dumps({'app_id': app_id, 'app_secret': app_secret}).encode('utf-8')
req = urllib.request.Request(url, data=data, headers={'Content-Type': 'application/json'})
with urllib.request.urlopen(req, timeout=10) as resp:
    token = json.loads(resp.read()).get('tenant_access_token')

doc_token = 'HrlGdwuJvoEIcDxXbFhcYmMtnrb'

def make_text_block(content, bold=False, italic=False):
    style = {}
    if bold:
        style["bold"] = True
    if italic:
        style["italic"] = True
    return {
        "block_type": 2,
        "text": {
            "elements": [{"text_run": {"content": content, "text_element_style": style if style else {}}}],
            "style": {}
        }
    }

def make_heading(level, content):
    bt = {1: 3, 2: 4, 3: 5}.get(level, 3)
    key = {3: "heading1", 4: "heading2", 5: "heading3"}.get(bt, "heading1")
    return {
        "block_type": bt,
        key: {
            "elements": [{"text_run": {"content": content, "text_element_style": {}}}],
            "style": {}
        }
    }

def make_bullet(content):
    return {
        "block_type": 12,
        "bullet": {
            "elements": [{"text_run": {"content": content, "text_element_style": {}}}],
            "style": {"indent_level": 1}
        }
    }

def make_divider():
    return {"block_type": 22}

def add_blocks(blocks, index=0):
    add_url = f'https://open.feishu.cn/open-apis/docx/v1/documents/{doc_token}/blocks/0/children'
    payload = json.dumps({"children": blocks, "index": index}).encode('utf-8')
    req = urllib.request.Request(add_url, data=payload, headers={
        'Content-Type': 'application/json',
        'Authorization': f'Bearer {token}'
    })
    with urllib.request.urlopen(req, timeout=30) as resp:
        return json.loads(resp.read())

# Batch 1: Title + Intro
batch1 = [
    make_heading(1, "一、产品定位与核心概念"),
    make_text_block("Role Simulator 是一个基于 5000 万消费者数据的角色模拟平台，帮助品牌快速定位目标人群并生成可交互的虚拟消费者画像。"),
    make_heading(2, "核心概念定义"),
    make_bullet("Role（角色）：基于人生阶段 × 城市等级聚类出的 30 个基础人群，是真实消费者的抽象聚合"),
    make_bullet("品牌 Role：品牌用户从大盘 Role 中选择，并叠加私有维度筛选后创建的目标人群包"),
    make_bullet("Profile（画像）：从品牌 Role 中采样，经 AI 生成 + 多学科访谈形成的可交互虚拟人"),
    make_divider(),
]

result = add_blocks(batch1)
print("Batch 1:", result.get('code'), result.get('msg'))
"}

